data = open('/testbed/data/sales.csv','rb').read()
# alternate text encodings
for enc in ('utf-16','utf-16-le','utf-16-be','latin-1','cp1252'):
    try:
        t = data.decode(enc)
        head = t[:80]
        print(enc, 'decoded; printable-ish head:', repr(head[:60]))
        if 'order_id' in t or ',' in t[:200]:
            print('  --> looks like CSV structure!')
    except Exception as e:
        print(enc, 'failed:', e)
# single-byte XOR scan for the known header
for k in range(256):
    x = bytes(b ^ k for b in data[:64])
    if b'order_id' in x or b'date' in x[:20]:
        print('XOR key', k, 'yields header:', x[:40])
        break
else:
    print('no single-byte XOR key produces the CSV header')
# compression probes
import gzip, zlib, bz2, lzma
for name, fn in [('gzip', lambda d: gzip.decompress(d)), ('zlib', lambda d: zlib.decompress(d)), ('bz2', lambda d: bz2.decompress(d)), ('lzma', lambda d: lzma.decompress(d))]:
    try:
        out = fn(data); print(name, 'OK, decompressed', len(out), 'bytes'); break
    except Exception as e:
        print(name, 'failed:', type(e).__name__)
